use std::sync::Arc;
use contextstore_client_rs::KvClient;
use contextstore_client_rs::rail_read::{RailLimits, RailReader, RailRoute};
use contextstore_client_rs::rdma::RdmaClientConfig;

async fn read_object() -> anyhow::Result<()> {
    let mut client = KvClient::connect("http://10.31.0.2:55151".into()).await
        .map_err(|error| anyhow::anyhow!(error.to_string()))?;
    let lookup = client.lookup_object("ffi", "railfuse-demo-v2").await?
        .ok_or_else(|| anyhow::anyhow!("object not found"))?;
    let mut destination = vec![0xA5; usize::try_from(lookup.descriptor.size)?];
    let limits = RailLimits { direct_staging: true, ..RailLimits::default() };
    let routes = vec![
        RailRoute::new("r0", "10.31.0.2:55153",
            RdmaClientConfig::new("10.31.0.2:55153", "rxe_c0")
                .with_port(1).with_gid_index(1)),
        RailRoute::new("r1", "10.31.0.2:55153",
            RdmaClientConfig::new("10.32.0.2:55154", "rxe_c1")
                .with_port(1).with_gid_index(1)),
    ];
    let reader = Arc::new(RailReader::new(routes, limits)?);
    let read = client.read_multi_rail_into(
        reader.clone(), "ffi", "railfuse-demo-v2", &mut destination, None
    ).await?;
    if let Some(bytes) = read {
        assert!(bytes <= destination.len());
        let published = &destination[..bytes];
        // Only this prefix belongs to the successful read.
        assert_eq!(published.len(), bytes);
        // Consume destination only after the high-level method succeeds.
    }
    for rail in reader.snapshots() {
        assert_eq!(rail.inflight_requests, 0);
        assert_eq!(rail.inflight_bytes, 0);
        assert_eq!(rail.registered_bytes, 0);
    }
    Ok(())
}
